def most_common_color(grid):
    """The color occupying the most cells."""
    from collections import Counter
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def fill_right_of_first(grid, fill=1, bg=None):
    """In each row, background cells to the right of the first non-background cell become fill."""
    if bg is None:
        bg = most_common_color(grid)
    foreign = {v for row in grid for v in row} - {bg}
    out = []
    for row in grid:
        if any(v in foreign for v in row):
            first = next(j for j, v in enumerate(row) if v in foreign)
            out.append([fill if (j > first and v == bg) else v for j, v in enumerate(row)])
        else:
            out.append(row)
    return out

